package com.primehr.security;
import com.primehr.integration.administrative.*;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Component;
@Component public class RrNominationPermissionGuard{public static final String CYCLE="primehr.rr-cycle";public static final String NOMINATION="primehr.rr-nomination";private final AdministrativeAuthorizationClient client;public RrNominationPermissionGuard(AdministrativeAuthorizationClient c){client=c;}public PermissionDataScope require(String feature,PrimeHrAction action,String token){EffectiveFeaturePermission p=client.resolve(feature,token);boolean allowed=p.administrator()||p.canAccess()&&switch(action){case ACCESS->true;case ADD->p.canAdd();case EDIT->p.canEdit();case ARCHIVE->p.canDelete();case SUBMIT->p.canSubmit();case FINALIZE->p.canFinalize();default->false;};if(!allowed)throw new AccessDeniedException("Rewards and Recognition cycle/nomination permission is required");PermissionDataScope scope=p.administrator()?PermissionDataScope.AGENCY_WIDE:p.dataScope();if(feature.equals(CYCLE)&&scope!=PermissionDataScope.AGENCY_WIDE)throw new AccessDeniedException("Award cycle administration requires Agency Wide scope");return scope;}}
